// Start from the last non-leaf node and heapify each node going up
for (int i = (size / 2) - 1; i >= 0; i--) {
    int smallest = i;
    int left = 2 * i + 1;
    int right = 2 * i + 2;

    // Check if left child is smaller than current smallest
    if (left < size && arr[left] < arr[smallest]) {
        smallest = left;
    }

    // Check if right child is smaller than current smallest
    if (right < size && arr[right] < arr[smallest]) {
        smallest = right;
    }

    // If smallest is not the current node, swap and continue heapifying
    if (smallest != i) {
        std::swap(arr[i], arr[smallest]);

        // Recursively heapify the affected subtree
        int child = smallest;
        while (true) {
            int leftChild = 2 * child + 1;
            int rightChild = 2 * child + 2;
            int minChild = child;

            if (leftChild < size && arr[leftChild] < arr[minChild]) {
                minChild = leftChild;
            }

            if (rightChild < size && arr[rightChild] < arr[minChild]) {
                minChild = rightChild;
            }

            if (minChild != child) {
                std::swap(arr[child], arr[minChild]);
                child = minChild;
            } else {
                break;
            }
        }
    }
}

